/**
 *  \brief This structure provides string encapsulation
 */
typedef struct SOPC_String
{
    int32_t Length;
    case SOPC_Double_Id:
    case SOPC_String_Id:
    case SOPC_DateTime_Id:
    case SOPC_Guid_Id:
